const projectId = $('Receive Project').first().json.project_id;
const project = $('Load Project').first().json;
const design = $('Load Selected Design Option').first().json;
const briefing = $('Load Briefing').first().json;
const agentPrompt = $('Load Agent Prompt').first().json;
const executionId = $('Start Execution').first().json.id;

const designContent = design || {};
const briefingContent = briefing || {};

const roomsAffected = briefingContent.rooms_affected || [];
const constraints = briefingContent.constraints || [];

const designSummary = design.title
  ? `Opcion ${design.option_number}: ${design.title}\n${design.description || ''}`
  : JSON.stringify(designContent, null, 2);

const roomsText = roomsAffected.length > 0
  ? roomsAffected.map(r => `- ${r.room}: ${r.intervention}`).join('\n')
  : '- Sin detalle disponible';

const constraintsText = constraints.length > 0
  ? constraints.map(c => `- ${c.description}`).join('\n')
  : '- Sin restricciones especificas';

const catalogItems = $('Load Supplier Catalog').all().map(i => i.json).filter(i => i.id);
let catalogText = '';
if (catalogItems.length > 0) {
  const byCategory = {};
  catalogItems.forEach(item => {
    if (!byCategory[item.category]) byCategory[item.category] = [];
    byCategory[item.category].push(`  - ${item.item_name}${item.brand ? ' (' + item.brand + ')' : ''}: ${item.unit_price}€/${item.unit || 'ud'} [${item.quality_tier || 'media'}]${item.notes ? ' — ' + item.notes : ''}`);
  });
  catalogText = `\n\nCATÁLOGO DE PROVEEDORES DEL ARQUITECTO (usa estos materiales preferentemente):\n`;
  Object.entries(byCategory).forEach(([cat, items]) => {
    catalogText += `${cat.toUpperCase()}:\n${items.join('\n')}\n`;
  });
  catalogText += '\nSi el catálogo no cubre alguna categoría, propón materiales estándar del mercado español con precio estimado.';
} else {
  catalogText = '\n\n(Sin catálogo de proveedores — proponer materiales estándar del mercado español con precios estimados 2024-2025)';
}

const outputFormat = `{\n  "materials": [\n    {\n      "category": "revestimientos|fontaneria|electricidad|carpinteria|estructura|acabados|instalaciones|otro",\n      "name": "string",\n      "description": "string",\n      "specification": "string",\n      "quantity": 0,\n      "unit": "m2|ml|ud|kg|l|otro",\n      "estimated_unit_cost": null,\n      "room": "string|null",\n      "priority": "esencial|recomendable|opcional",\n      "notes": "string|null"\n    }\n  ],\n  "analysis_summary": "string"\n}`;

const userPrompt = `Analiza el proyecto de reforma y genera la lista completa de materiales necesarios para ejecutar la opcion de diseno seleccionada.\n\nPROYECTO:\n- Tipo: ${project.project_type || 'reforma'}\n- Localizacion: ${project.location_city || ''}, ${project.location_province || ''}\n- Inmueble: ${project.property_type || ''}\n- Superficie: ${project.property_area_m2 || ''} m2\n\nOPCION DE DISENO SELECCIONADA:\n${designSummary}\n\nINTERVENCIONES PREVISTAS:\n${roomsText}\n\nRESTRICCIONES:\n${constraintsText}${catalogText}\n\nINSTRUCCIONES:\n- Genera un material por cada elemento constructivo relevante\n- Usa PREFERENTEMENTE materiales del catálogo del arquitecto cuando correspondan\n- Para materiales del catálogo usa su precio exacto en estimated_unit_cost\n- Para materiales no en catálogo estima precios del mercado español 2024-2025\n- Incluye materiales de demolicion, construccion, acabados e instalaciones\n- Para cantidad y unidad usa valores realistas estimados segun la superficie del proyecto\n- Marca como esencial los materiales criticos\n- Usa el campo room para agrupar por estancia cuando sea posible\n- Incluye especificaciones tecnicas en el campo specification\n\nResponde EXCLUSIVAMENTE con JSON valido:\n${outputFormat}`;

// === STUDIO PROFILE INJECTION (B23) ===
const _studio = $('Load Studio Profile').first().json || {};
function _safeStudio(v){ if(v==null)return null; if(typeof v==='string'){try{return JSON.parse(v);}catch(e){return v;}} return v; }
const _id=_safeStudio(_studio.identity)||{},_priorities=_safeStudio(_studio.priorities)||[],_matPref=_safeStudio(_studio.materials_pref)||{};
const _SP_MAT_LINES=[];
_SP_MAT_LINES.push('Estudio: '+(_id.nombre_estudio||'estudio')+' en '+(_id.ciudad||'Espana')+'.');
_SP_MAT_LINES.push('GAMA POR DEFECTO del estudio: '+(_matPref.gama_default||'media')+'. Prefiere proveedores locales: '+(_matPref.prefiere_local?'si':'no')+'.');
const _marcas = _matPref.marcas_preferidas_por_categoria || {};
if (Object.keys(_marcas).length>0) {
  _SP_MAT_LINES.push('MARCAS PREFERIDAS por categoria del estudio:');
  Object.entries(_marcas).forEach(([k,v])=>_SP_MAT_LINES.push('- '+k+': '+(Array.isArray(v)?v.join(', '):v)));
}
_SP_MAT_LINES.push('PRIORIDADES (orden estricto):');
(_priorities||[]).forEach(p=>_SP_MAT_LINES.push((p.orden||'?')+'. '+(p.prioridad||'')));
const _SP_MAT=_SP_MAT_LINES.join('\n');
// === END STUDIO PROFILE INJECTION ===
return [{ json: { agent_name: 'agent_materials',
  project_id: projectId,
  execution_id: executionId,
  prompt_system: _SP_MAT + '\n\n' + (agentPrompt.content || 'Eres el Agente de Materiales de un estudio de arquitectura. Tu funcion es generar listas de materiales precisas y detalladas para proyectos de reforma, con especificaciones tecnicas y estimaciones de cantidad realistas.'),
  prompt_user: userPrompt,
  model: (agentPrompt.model_recommended || 'claude-sonnet-4-20250514').trim(),
  temperature: agentPrompt.temperature || 0.3
}}];

const llmResponse = $('Call LLM').first().json;
const projectId = $('Receive Project').first().json.project_id;
const executionId = $('Start Execution').first().json.id;

let parsed = {};
try {
  const content = llmResponse.content || llmResponse.text || llmResponse.message || JSON.stringify(llmResponse);
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
} catch(e) {
  parsed = { materials: [], analysis_summary: 'Error parsing LLM response: ' + e.message };
}

const materials = parsed.materials || [];
const summary = parsed.analysis_summary || '';

if (materials.length === 0) {
  return [{ json: {
    project_id: projectId,
    execution_id: executionId,
    category: 'otro',
    name: 'Sin materiales identificados',
    description: summary,
    specification: '',
    quantity: null,
    unit: 'ud',
    estimated_unit_cost: null,
    room: null,
    priority: 'informativo',
    notes: null,
    analysis_summary: summary
  }}];
}

return materials.map(m => ({ json: {
  project_id: projectId,
  execution_id: executionId,
  category: m.category || 'otro',
  name: m.name || 'Sin nombre',
  description: m.description || '',
  specification: m.specification || '',
  quantity: m.quantity != null ? m.quantity : null,
  unit: m.unit || 'ud',
  estimated_unit_cost: m.estimated_unit_cost != null ? m.estimated_unit_cost : null,
  room: m.room || null,
  priority: m.priority || 'recomendable',
  notes: m.notes || null,
  analysis_summary: summary
}}));

const allMaterials = $input.all().map(i => i.json);
const seen = new Set();
const mainItems = [];
for (const m of allMaterials) {
  if (!seen.has(m.category) && m.category !== 'otro') {
    seen.add(m.category);
    mainItems.push({ json: {
      material_name: m.name,
      category: m.category,
      quality_tier: 'media'
    }});
  }
}
if (mainItems.length === 0) {
  return [{ json: { material_name: 'placeholder', category: 'placeholder', quality_tier: 'media', _skip: true } }];
}
return mainItems.slice(0, 6);

const priceItems = $input.all().map(i => i.json);
const allMaterials = $('Parse Materials').all().map(i => i.json);
const priceMap = {};
priceItems.forEach(p => {
  if (p.avg_price && p.category) {
    priceMap[p.category] = p;
  }
});
return allMaterials.map(m => {
  const enrichment = priceMap[m.category];
  if (enrichment && enrichment.avg_price && !m.estimated_unit_cost) {
    return { json: {
      ...m,
      estimated_unit_cost: enrichment.avg_price,
      price_source: enrichment.source || 'web_search',
      source_url: enrichment.source_url || null
    }};
  }
  return { json: {
    ...m,
    price_source: m.estimated_unit_cost ? 'llm_estimate' : 'not_found',
    source_url: null
  }};
});

const items = $input.all();
return [{ json: {
  project_id: $('Receive Project').first().json.project_id,
  execution_id: $('Start Execution').first().json.id,
  materials_count: items.length,
  analysis_summary: $('Parse Materials').first().json.analysis_summary || ''
}}];
